upstream api {
  least_conn;                    # dynamic: trust active-connection signal
  server 10.0.1.11:8080 max_fails=3 fail_timeout=15s slow_start=30s;
  server 10.0.1.12:8080 max_fails=3 fail_timeout=15s slow_start=30s;
  server 10.0.1.13:8080 max_fails=3 fail_timeout=15s slow_start=30s;
  keepalive 256;                # reuse backend conns, avoid handshake storm
}
server {
  listen 443 ssl;
  location / {
    proxy_pass http://api;
    proxy_next_upstream error timeout http_502 http_503 non_idempotent off;
    proxy_connect_timeout 2s;
    proxy_read_timeout 5s;
    health_check interval=5s fails=3 passes=2 uri=/healthz;
  }
  location /healthz { return 200; }  # LB liveness != app readiness
}
